function COMB-CORES(P, Q, r, x0):
    g <- gcd(r, Q) ; s <- r / g
    A <- zero matrix of shape (P, s)
    for p in 0 .. P-1:
        c <- ((p * Q) mod r) / g          # exact division: g divides p*Q mod r
        A[p][c] <- 1
    B <- zero matrix of shape (s, Q)
    for c in 0 .. s-1:
        for q in 0 .. Q-1:
            if (c*g + q) mod r == x0 mod r: B[c][q] <- 1
    return (A, B)                          # A @ B is the comb, exactly

