"""Algorithm B: construction of the provably optimal two-core tensor train of a
periodic comb, together with a verification that the cores multiply back to the
state."""

from math import gcd
from typing import List


def comb_cores(P: int, Q: int, r: int, x0: int) -> tuple[List[List[int]], List[List[int]]]:
    """Return cores A (P x s) and B (s x Q), s = r / gcd(r, Q), with A @ B equal to
    the reshaped comb matrix.  The left core records which element of the subgroup
    generated by Q in Z/rZ the left index reaches; the right core completes that
    residue to x0.  Cost O(P*s + s*Q); the bond s is optimal whenever s <= P."""
    g = gcd(r, Q)
    s = r // g
    A = [[0] * s for _ in range(P)]
    for p in range(P):
        c = ((p * Q) % r) // g          # the reachable residue, divided by g
        A[p][c] = 1
    B = [[1 if (c * g + q) % r == x0 % r else 0 for q in range(Q)] for c in range(s)]
    return A, B


def contract(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    """Dense contraction of the two cores over the bond index."""
    s = len(B)
    return [
        [sum(A[p][c] * B[c][q] for c in range(s)) for q in range(len(B[0]))]
        for p in range(len(A))
    ]


def comb_matrix(P: int, Q: int, r: int, x0: int) -> List[List[int]]:
    return [
        [1 if (p * Q + q) % r == x0 % r else 0 for q in range(Q)] for p in range(P)
    ]


def verify(P: int, Q: int, r: int, x0: int) -> bool:
    A, B = comb_cores(P, Q, r, x0)
    return contract(A, B) == comb_matrix(P, Q, r, x0)


if __name__ == "__main__":
    for P in range(1, 13):
        for Q in range(1, 13):
            for r in range(1, Q + 1):
                for x0 in range(4):
                    assert verify(P, Q, r, x0), (P, Q, r, x0)
    print("optimal tensor train reconstructs the comb in all tested cases")
